 act(c,a,"transfer","front",b);no("transfer freezes old owner",()->cmd(c,a,"front","focus",55,0));String proposal=(String)((Map<?,?>)payload(c,"front").get("proposal")).get("id");no("recipient consent cannot be forged by from",()->act(c,a,"accept","front",proposal));act(c,b,"accept","front",proposal);no("old owner revoked after acceptance",()->cmd(c,a,"front","focus",55,0));PayloadCore97.Tx focus=cmd(c,b,"front","focus",55,0);c.receive(v.get("ackFocus"),++now);c.receive(v.get("focus"),++now);ok("recipient new command works",focus.state.equals("OBSERVATION_CONSISTENT_UNATTRIBUTED"));
 PayloadCore97.Tx capture=cmd(c,b,"front","capture",0,0);act(c,b,"release","front","");c.receive(v.get("captureAck"),++now);c.receive(v.get("image"),++now);ok("revoked pending cannot resurrect from late ACK",capture.state.startsWith("UNKNOWN_"));no("released owner cannot send",()->cmd(c,b,"front","authority",0,0));ok("no images or execution claimed",snap(c).get("actualImages").equals(0)&&snap(c).get("executionProven").equals(false));
 PayloadCore97 g=fresh();String ga=join(g,"pilot-a");act(g,ga,"claim","front","");PayloadCore97.Tx gt=cmd(g,ga,"front","gimbal",-30,10);g.receive(v.get("gimbalAck"),++now);g.receive(v.get("gimbalWrongDevice"),++now);ok("wrong manager device does not complete",gt.state.equals("ACK_ACCEPTED_NOT_EXECUTION"));g.receive(v.get("gimbal"),++now);ok("manager quaternion matches device and angle",gt.state.equals("OBSERVATION_CONSISTENT_UNATTRIBUTED"));act(g,ga,"claim","center","");no("shared manager ACK key quarantined across devices",()->cmd(g,ga,"center","gimbal",-30,10));
 PayloadCore97 h=fresh();String ha=join(h,"pilot-a"),hb=join(h,"payload-b");act(h,ha,"claim","front","");act(h,ha,"transfer","front",hb);String hp=(String)((Map<?,?>)payload(h,"front").get("proposal")).get("id");act(h,hb,"decline","front",hp);ok("decline revokes no restore",payload(h,"front").get("ownerSid")==null);act(h,ha,"claim","front","");act(h,ha,"lose","front","");no("lost station cannot send",()->cmd(h,ha,"front","zoom",40,0));ok("explicit operator loss revokes owner",payload(h,"front").get("ownerSid")==null);
 PayloadCore97 e=fresh();String ea=join(e,"pilot-a");act(e,ea,"claim","front","");for(int n=0;n<32;n++){now=2000+n*1000;e.receive(v.get("pulse"+n),now);e.heartbeat(ea,now);}ok("lease expiry with fresh operator never regrants",payload(e,"front").get("ownerSid")==null);
 PayloadCore97 st=fresh();String sta=join(st,"pilot-a");act(st,sta,"claim","front","");for(int n=0;n<16;n++){now=2000+n*1000;st.receive(v.get("pulse"+n),now);}ok("operator heartbeat loss clears authority",payload(st,"front").get("ownerSid")==null&&!station(st,sta).get("alive").equals(true));
 PayloadCore97 boot=fresh();String ba=join(boot,"pilot-a");act(boot,ba,"claim","front","");no("payload boot regression closes entire session",()->boot.receive(v.get("bootRegression"),++now));ok("boot clears all grants",payload(boot,"front").get("ownerSid")==null);
