 PayloadCore97 split=new PayloadCore97();for(int i=0;i<whole.length;i++)split.receive(Arrays.copyOfRange(whole,i,i+1),1000);ok("one-byte full stream fragments decoded",(Boolean)split.snapshot(1000).get("apFresh"));PayloadCore97 remote=fresh();remote.receive(v.get("foreignCamera"),++now);ok("foreign system ignored no extra camera",((List<?>)remote.snapshot(now).get("payloads")).size()==3);
